export type ReferenceEntry = {
	path: string,
	/**  `file` / `directory`（未知值 → `invalid_enum`）。 */
	kind: string,
};

/**  M6-01/ADR-019：`rule_add` 参数（`{ name, resource, action, target_kind, target?, decision, priority? }`）。 */
